
const branches=['Hyderabad','Bengaluru','Chennai','Mumbai','Delhi'];const depts=['Biochemistry','Hematology','Immunology','Microbiology','Molecular'];let period='daily';const $=id=>document.getElementById(id);$('branch').innerHTML='<option value="">All branches</option>'+branches.map(b=>`<option>${b}</option>`).join('');function resetDept(){$('dept').innerHTML='<option value="">All departments</option>'+depts.map(d=>`<option>${d}</option>`).join('')}resetDept();function seed(){return [...$('date').value].reduce((a,c)=>a+c.charCodeAt(0),0)}function record(b,d){let bi=branches.indexOf(b),di=depts.indexOf(d),s=seed(),m=period==='monthly'?new Date(Number($('date').value.slice(0,4)),Number($('date').value.slice(5,7)),0).getDate():1,runs=(38+bi*7+di*9+s%11)*m,failed=(1+(bi+di+s)%4)*m;return{samples:(374+bi*101+di*73+s%53)*m,runs,failed,passed:runs-failed}}function sum(bs,ds){let a={samples:0,runs:0,passed:0,failed:0};bs.forEach(b=>ds.forEach(d=>{let r=record(b,d);Object.keys(a).forEach(k=>a[k]+=r[k])}));return a}function scope(){return {bs:$('branch').value?[$('branch').value]:branches,ds:$('dept').value?[$('dept').value]:depts}}const fmt=n=>n.toLocaleString('en-IN');const pct=(a,b)=>(b?a/b*100:0).toFixed(1);function setPeriod(p){period=p;$('daily').classList.toggle('selected',p==='daily');$('monthly').classList.toggle('selected',p==='monthly');$('date').type=p==='daily'?'date':'month';$('date').value=p==='daily'?'2026-10-21':'2026-10';$('dateLabel').textContent=p==='daily'?'Date':'Month';render()}function render(){let {bs,ds}=scope(),a=sum(bs,ds),pass=pct(a.passed,a.runs),fail=pct(a.failed,a.runs);$('kpis').innerHTML=[['Patient samples',fmt(a.samples),'Samples processed',''],['Total QC runs',fmt(a.runs),'Quality control runs',''],['QC passed',fmt(a.passed),'Successfully passed','green'],['QC failed',fmt(a.failed),'Requires review','red'],['QC pass rate',pass+'%','Of total QC runs','green'],['QC failure rate',fail+'%','Of total QC runs','red']].map(([l,v,f,c])=>`<div class="card kpi"><div class="kpi-label">${l}</div><div class="kpi-value ${c}">${v}</div><div class="kpi-foot">${f}</div></div>`).join('');let names=$('branch').value?ds:bs;let vals=names.map(n=>$('branch').value?sum(bs,[n]):sum([n],ds));$('performanceTitle').textContent=period==='daily'?'Daily QC performance':'Monthly QC performance';$('performanceSub').textContent=`${$('branch').value||'All branches'} · ${$('dept').value||'All departments'} · ${$('date').value}`;drawBars(names,vals);drawTrend(a);drawCauses(a.failed);let completed=Math.round(a.failed*.72),pending=a.failed-completed;$('actions').innerHTML=`<div class="action-num"><strong>${fmt(a.failed)}</strong><span>Total actions</span></div><div class="action-num"><strong class="green">${fmt(completed)}</strong><span>Completed</span></div><div class="action-num"><strong style="color:#bc904b">${fmt(pending)}</strong><span>Pending</span></div>`;$('progress').style.width=completed/a.failed*100+'%';$('actionNote').textContent=`${pct(completed,a.failed)}% of corrective and preventive actions completed`;$('tableTitle').textContent=$('branch').value?($('dept').value?'Assay / QC details':'Department performance'):'Branch performance';$('nameHeading').textContent=$('branch').value?'Department':'Branch';$('back').style.display=$('branch').value?'inline-block':'none';$('rowCount').textContent=names.length+' '+($('branch').value?'departments':'branches');$('rows').innerHTML=names.map((n,i)=>{let r=vals[i];return `<tr><td><button class="branch-link" onclick="drill('${n}')">${n} &nbsp; ›</button></td><td>${fmt(r.samples)}</td><td>${fmt(r.runs)}</td><td class="green">${fmt(r.passed)}</td><td class="red">${fmt(r.failed)}</td><td><div class="rate"><span class="green">${pct(r.passed,r.runs)}%</span><span class="mini-track"><i style="width:${pct(r.passed,r.runs)}%"></i></span></div></td><td class="red">${pct(r.failed,r.runs)}%</td><td><span class="pill">${fmt(r.failed-Math.round(r.failed*.72))} pending</span></td></tr>`}).join('')}
function drawBars(names,vals){let max=Math.max(100,Math.ceil(Math.max(...vals.map(r=>r.runs))/100)*100),w=520/names.length;let s='';for(let i=0;i<=4;i++){let y=175-i*38;s+=`<line x1="48" y1="${y}" x2="604" y2="${y}" stroke="#edf1f2"/><text x="35" y="${y+4}" text-anchor="end" fill="#9aa7ad" font-size="10">${Math.round(max*i/4)}</text>`}vals.forEach((r,i)=>{let x=65+i*w,h=r.passed/max*152,f=r.failed/max*152;s+=`<rect x="${x}" y="${175-h}" width="25" height="${h}" rx="3" fill="#35B34A"><title>${names[i]}: ${r.passed} passed</title></rect><rect x="${x+30}" y="${175-f}" width="14" height="${f}" rx="3" fill="#e77b7b"><title>${names[i]}: ${r.failed} failed</title></rect><text x="${x+22}" y="199" text-anchor="middle" fill="#8a9ba3" font-size="9">${names[i]}</text>`});$('bars').innerHTML=s}
function drawTrend(a){let count=7,base=+pct(a.failed,a.runs);let labels=[],rates=[];for(let i=0;i<count;i++){let dt=new Date($('date').value+'T12:00:00');if(period==='monthly'){dt=new Date($('date').value+'-15T12:00:00');dt.setMonth(dt.getMonth()-(6-i));labels.push(dt.toLocaleDateString('en',{month:'short'}))}else{dt.setDate(dt.getDate()-(6-i));labels.push(dt.toLocaleDateString('en',{day:'numeric',month:'short'}))}rates.push(i===6?base:Math.max(1,base+Math.sin(i+seed())*1.6))}let s='';[0,25,50,75,100].forEach(n=>{let y=162-n*1.4;s+=`<line x1="35" y1="${y}" x2="378" y2="${y}" stroke="#edf1f2"/><text x="26" y="${y+3}" fill="#9aa7ad" font-size="9" text-anchor="end">${n}%</text>`});['pass','fail'].forEach(t=>{let points=rates.map((r,i)=>`${43+i*54},${162-(t==='pass'?100-r:r)*1.4}`).join(' '),c=t==='pass'?'#35B34A':'#e76c6c';s+=`<polyline points="${points}" fill="none" stroke="${c}" stroke-width="2.5" stroke-linejoin="round"/>`;rates.forEach((r,i)=>s+=`<circle cx="${43+i*54}" cy="${162-(t==='pass'?100-r:r)*1.4}" r="3" fill="white" stroke="${c}" stroke-width="2"><title>${labels[i]}: ${(t==='pass'?100-r:r).toFixed(1)}%</title></circle>`)});labels.forEach((l,i)=>s+=`<text x="${43+i*54}" y="187" fill="#8a9ba3" font-size="8" text-anchor="middle">${l}</text>`);$('trend').innerHTML=s;$('trendSub').textContent=period==='daily'?'Daily pass and failure rates · last 7 days':'Monthly pass and failure rates · last 7 months'}
function drawCauses(total){let colors=['#278436','#35B34A','#a3d9ab','#dbb875'],labels=['Reagent-related','Calibration deviation','Instrument variation','Procedural error'],counts=[Math.round(total*.4),Math.round(total*.28),Math.round(total*.2)];counts.push(total-counts.reduce((a,b)=>a+b,0));let s='<circle cx="90" cy="90" r="65" fill="none" stroke="#f0f4f3" stroke-width="20"/>',off=0;counts.forEach((n,i)=>{let len=n/total*408.4;s+=`<circle cx="90" cy="90" r="65" fill="none" stroke="${colors[i]}" stroke-width="20" stroke-dasharray="${Math.max(0,len-3)} ${408.4-Math.max(0,len-3)}" stroke-dashoffset="${-off}" transform="rotate(-90 90 90)"><title>${labels[i]}: ${n}</title></circle>`;off+=len});s+=`<text x="90" y="88" text-anchor="middle" font-family="Manrope,Arial" font-size="28" font-weight="800" fill="#233e48">${fmt(total)}</text><text x="90" y="108" text-anchor="middle" font-size="10" fill="#94a1a6">QC failures</text>`;$('donut').innerHTML=s;$('causes').innerHTML=counts.map((n,i)=>`<div class="cause"><span><i class="dot" style="background:${colors[i]}"></i>${labels[i]}</span><b>${pct(n,total)}%</b></div>`).join('')}
function drill(n){if(!$('branch').value){$('branch').value=n;resetDept();render()}else{$('dept').value=n;render();openDetails()}}function goBack(){if($('dept').value){$('dept').value=''}else{$('branch').value='';resetDept()}render()}function openDetails(){let dep=$('dept').value||'Biochemistry';let assay={Biochemistry:'Glucose · Level 2',Hematology:'CBC · Level 1',Immunology:'TSH · Level 2',Microbiology:'Culture control',Molecular:'PCR positive control'}[dep];$('detailScope').textContent=($('branch').value||'All branches')+' / '+($('dept').value||'All departments')+' · '+$('date').value;$('detailRows').innerHTML=[[assay,'Reagent-related','Replace reagent lot','Verify new lots','Completed'],[assay,'Calibration deviation','Recalibrate assay','Review calibration schedule','Completed'],[assay,'Instrument variation','Instrument check pending','Schedule maintenance','Pending'],[assay,'Procedural error','Repeat QC run','Procedure refresher pending','Pending']].map(r=>'<tr>'+r.map((c,i)=>`<td>${i===4?`<span class="pill ${c==='Completed'?'done':''}">${c}</span>`:c}</td>`).join('')+'</tr>').join('');$('details').showModal()}function showAnalytics(){$('dashboard').style.display='none';$('integration').style.display='block';$('analyticsNav').classList.add('active');$('qcNav').classList.remove('active');$('crumb').textContent='Analytical Dashboard'}function showQC(){$('dashboard').style.display='block';$('integration').style.display='none';$('qcNav').classList.add('active');$('analyticsNav').classList.remove('active');$('crumb').textContent='Quality Control'}render();


const assayMap={Biochemistry:['Glucose','Creatinine'],Hematology:['CBC','Hemoglobin'],Immunology:['TSH','Ferritin'],Microbiology:['Culture control','Susceptibility control'],Molecular:['PCR positive control','PCR negative control']};
const causeNames=['Reagent-related','Calibration deviation','Instrument variation','Procedural error'];let currentRecords=[],currentFailures=[];let chartRecords=null;
function toggleMore(){let open=$('morePanel').hidden;$('morePanel').hidden=!open;$('moreButton').setAttribute('aria-expanded',String(open));$('moreButton').textContent=open?'More filters ▴':'More filters ▾'}
function clearMore(){['result','causeFilter','statusFilter','assayFilter'].forEach(id=>$(id).value='');render()}
function updateAssays(){let previous=$('assayFilter').value,options=($('dept').value?[ $('dept').value]:depts).flatMap(d=>assayMap[d]);$('assayFilter').innerHTML='<option value="">All assays</option>'+options.map(a=>'<option>'+a+'</option>').join('');if(options.includes(previous))$('assayFilter').value=previous}
function selectedDates(){let value=$('date').value;if(!value)return null;let start=value,end=value;if(period==='monthly'){start=value+'-01';let [y,m]=value.split('-').map(Number);end=value+'-'+new Date(y,m,0).getDate()}else if(period==='custom'){end=$('endDate').value}if(!end||start>end)return null;return {start,end}}
function makeRecords(start,end){let records=[];let date=new Date(start+'T00:00:00Z'),last=new Date(end+'T00:00:00Z');for(;date<=last;date.setUTCDate(date.getUTCDate()+1)){let day=date.toISOString().slice(0,10),n=Math.floor(date.getTime()/86400000);branches.forEach((b,bi)=>depts.forEach((d,di)=>assayMap[d].forEach((assay,ai)=>{let runs=18+(n+bi*7+di*3+ai*5)%14;for(let j=0;j<runs;j++){let failure=(j+bi+di+ai+n)%19===0,ci=(n+bi+di+ai+j)%4;records.push({date:day,branch:b,dept:d,assay,result:failure?'Failed':'Passed',cause:failure?causeNames[ci]:'',status:failure?((n+j+bi)%4===0?'Pending':'Completed'):'',samples:12+(j+di)%7})}})))}return records}
function matches(r,bs,ds){return bs.includes(r.branch)&&ds.includes(r.dept)&&(!$('assayFilter').value||r.assay===$('assayFilter').value)&&(!$('result').value||r.result===$('result').value)&&(!$('causeFilter').value||r.cause===$('causeFilter').value)&&(!$('statusFilter').value||r.status===$('statusFilter').value)}
function summarize(records){return records.reduce((a,r)=>{a.samples+=r.samples;a.runs++;a[r.result==='Passed'?'passed':'failed']++;return a},{samples:0,runs:0,passed:0,failed:0})}
sum=function(bs,ds){return summarize((chartRecords||currentRecords).filter(r=>matches(r,bs,ds)))};
const originalRender=render;
render=function(){updateAssays();let dates=selectedDates();$('rangeError').textContent=dates?'':'Select valid dates. The start date must be on or before the end date.';currentRecords=dates?makeRecords(dates.start,dates.end):[];let {bs,ds}=scope(),filtered=currentRecords.filter(r=>matches(r,bs,ds));currentFailures=filtered.filter(r=>r.result==='Failed');originalRender();$('performanceTitle').textContent=period==='custom'?'QC performance · custom range':period==='monthly'?'Monthly QC performance':'Daily QC performance';$('performanceSub').textContent=($('branch').value||'All branches')+' · '+($('dept').value||'All departments')+' · '+(dates?dates.start+(dates.end!==dates.start?' to '+dates.end:''):'Invalid date range');let extras=['result','causeFilter','statusFilter','assayFilter'].filter(id=>$(id).value).map(id=>$(id).value);$('filterSummary').textContent=(extras.length?'Active filters: '+extras.join(' · ')+'. ':'')+(filtered.length?fmt(filtered.length)+' matching QC runs. ':'No matching QC records. ')+(extras.length?'Percentages use matching QC runs. ':'')+'Patient samples are associated with the matching demo QC runs; counts are illustrative.';$('moreButton').textContent='More filters'+(extras.length?' ('+extras.length+')':'')+($('morePanel').hidden?' ▾':' ▴');let completed=currentFailures.filter(r=>r.status==='Completed').length,pending=currentFailures.length-completed;$('actions').innerHTML=[['Total actions',currentFailures.length,''],['Completed',completed,'green'],['Pending',pending,'']].map(([l,n,c])=>'<div class="action-num"><strong class="'+c+'">'+fmt(n)+'</strong><span>'+l+'</span></div>').join('');$('progress').style.width=pct(completed,currentFailures.length)+'%';$('actionNote').textContent=currentFailures.length?pct(completed,currentFailures.length)+'% of matching actions completed':'No actions match the selected filters';let names=$('branch').value?ds:bs;[...$('rows').children].forEach((row,i)=>{let failures=currentRecords.filter(r=>matches(r,$('branch').value?bs:[names[i]],$('branch').value?[names[i]]:ds)&&r.result==='Failed'&&r.status==='Pending').length;row.lastElementChild.innerHTML='<span class="pill">'+fmt(failures)+' pending</span>'});$('tableTitle').textContent=$('branch').value?'Department performance':'Branch performance'};
drawCauses=function(total){let colors=['#278436','#35B34A','#a3d9ab','#dbb875'],offset=0;let svg='<circle cx="90" cy="90" r="65" fill="none" stroke="#edf2f1" stroke-width="20"/>';let counts=causeNames.map(c=>currentFailures.filter(r=>r.cause===c).length);counts.forEach((n,i)=>{let len=total?n/total*408.4:0;if(n)svg+='<circle cx="90" cy="90" r="65" fill="none" stroke="'+colors[i]+'" stroke-width="20" stroke-dasharray="'+len+' '+(408.4-len)+'" stroke-dashoffset="'+(-offset)+'" transform="rotate(-90 90 90)"/>';offset+=len});$('donut').innerHTML=svg+'<text x="90" y="88" text-anchor="middle" font-size="28" font-weight="800" fill="#233e48">'+fmt(total)+'</text><text x="90" y="108" text-anchor="middle" font-size="10" fill="#94a1a6">QC failures</text>';$('causes').innerHTML=counts.map((n,i)=>'<div class="cause"><span><i class="dot" style="background:'+colors[i]+'"></i>'+causeNames[i]+'</span><b>'+pct(n,total)+'%</b></div>').join('')};
drawTrend=function(){let dates=selectedDates(),buckets=[];if(dates){if(period==='daily'){let end=new Date(dates.end+'T00:00:00Z');for(let i=6;i>=0;i--){let d=new Date(end);d.setUTCDate(d.getUTCDate()-i);let key=d.toISOString().slice(0,10);buckets.push({start:key,end:key,label:key.slice(5)})}}else if(period==='monthly'){let end=new Date(dates.start+'T00:00:00Z');for(let i=6;i>=0;i--){let d=new Date(end);d.setUTCMonth(d.getUTCMonth()-i);let key=d.toISOString().slice(0,7),last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).toISOString().slice(0,10);buckets.push({start:key+'-01',end:last,label:key})}}else{let start=new Date(dates.start+'T00:00:00Z').getTime(),days=Math.round((new Date(dates.end+'T00:00:00Z')-start)/86400000)+1,count=Math.min(days,7);for(let i=0;i<count;i++){let a=new Date(start+Math.floor(days*i/count)*86400000).toISOString().slice(0,10),b=new Date(start+(Math.floor(days*(i+1)/count)-1)*86400000).toISOString().slice(0,10);buckets.push({start:a,end:b,label:a.slice(5)+(a===b?'':'–'+b.slice(5))})}}}let s='';[0,25,50,75,100].forEach(n=>{let y=162-n*1.4;s+='<line x1="35" y1="'+y+'" x2="378" y2="'+y+'" stroke="#edf1f2"/><text x="26" y="'+(y+3)+'" fill="#9aa7ad" font-size="9" text-anchor="end">'+n+'%</text>'});let {bs,ds}=scope();let totals=buckets.map(b=>summarize(makeRecords(b.start,b.end).filter(r=>matches(r,bs,ds))));['passed','failed'].forEach((k,ki)=>{let c=ki?'#e76c6c':'#35B34A',points=[];totals.forEach((a,i)=>{let x=buckets.length===1?205:43+i*324/(buckets.length-1),rate=+pct(a[k],a.runs),y=162-rate*1.4;if(a.runs){points.push(x+','+y);s+='<circle cx="'+x+'" cy="'+y+'" r="3" fill="'+c+'"><title>'+buckets[i].start+' to '+buckets[i].end+': '+rate+'%</title></circle>'}else{if(points.length)s+='<polyline points="'+points.join(' ')+'" fill="none" stroke="'+c+'" stroke-width="2"/>';points=[]}});s+='<polyline points="'+points.join(' ')+'" fill="none" stroke="'+c+'" stroke-width="2"/>'});buckets.forEach((b,i)=>s+='<text x="'+(buckets.length===1?205:43+i*324/(buckets.length-1))+'" y="187" fill="#8a9ba3" font-size="8" text-anchor="middle">'+b.label+'</text>');$('trend').innerHTML=s;$('trendSub').textContent=period==='custom'?'Selected range · daily or grouped daily rates':period==='monthly'?'Last 7 months · selected filters':'Last 7 days · selected filters'};
setPeriod=function(p){let prior=$('date').value||'2026-10-21';period=p;$('date').type=p==='monthly'?'month':'date';$('date').value=p==='monthly'?prior.slice(0,7):prior.length===7?prior+'-01':prior;$('endField').hidden=p!=='custom';$('endField').style.display=p==='custom'?'flex':'none';$('dateLabel').textContent=p==='monthly'?'Month':p==='custom'?'From':'Date';render()};
openDetails=function(){let dates=selectedDates();$('detailScope').textContent=($('branch').value||'All branches')+' / '+($('dept').value||'All departments')+' · '+(dates?dates.start+' to '+dates.end:'Invalid dates');let groups=new Map;currentFailures.forEach(r=>{let key=[r.branch,r.dept,r.assay,r.cause,r.status].join('|');if(!groups.has(key))groups.set(key,{...r,count:0});groups.get(key).count++});$('detailRows').innerHTML=[...groups.values()].map(r=>{let i=causeNames.indexOf(r.cause),correct=['Replace reagent lot','Recalibrate assay','Check instrument','Repeat QC run'][i],prevent=['Verify new lots','Review calibration schedule','Schedule maintenance','Procedure refresher'][i];return '<tr><td>'+r.assay+'<br><small>'+r.branch+' · '+r.dept+' · '+r.count+' runs</small></td><td>'+r.cause+'</td><td>'+correct+'</td><td>'+prevent+'</td><td><span class="pill '+(r.status==='Completed'?'done':'')+'">'+r.status+'</span></td></tr>'}).join('')||'<tr><td colspan="5">No QC failures or actions match the selected filters.</td></tr>';if(!$('details').open)$('details').showModal()};
$('dept').onchange=()=>{updateAssays();render()};$('endField').style.display='none';updateAssays();render();


function exportCSV(){
let dates=selectedDates();if(!dates){$('rangeError').textContent='Select a valid date range before exporting.';return}
let {bs,ds}=scope(),records=currentRecords.filter(r=>matches(r,bs,ds));
const correction={'Reagent-related':'Replace reagent lot','Calibration deviation':'Recalibrate assay','Instrument variation':'Check instrument','Procedural error':'Repeat QC run'};
const prevention={'Reagent-related':'Verify new lots','Calibration deviation':'Review calibration schedule','Instrument variation':'Schedule maintenance','Procedural error':'Procedure refresher'};
const rows=[['Date','Branch','Department','Assay','Patient samples (illustrative association)','QC result','Root cause','Corrective action','Preventive action','Action status'],...records.map(r=>[r.date,r.branch,r.dept,r.assay,r.samples,r.result,r.cause,correction[r.cause]||'',prevention[r.cause]||'',r.status])];
const cell=value=>'"'+String(value??'').replace(/^[=+@-]/,match=>"'"+match).replace(/"/g,'""')+'"';
const csv='\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\r\n');
const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));let link=document.createElement('a');link.href=url;link.download='IT-DOES-QC-demo-'+dates.start+'-to-'+dates.end+'.csv';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
$('exportStatus').textContent=records.length?fmt(records.length)+' matching demo QC records exported.':'No matching records. Exported CSV contains column headings only.';
}


const priorDates=selectedDates;
selectedDates=function(){
 if(period==='quarterly'||period==='yearly'){let year=Number($('yearSelect').value);if(!Number.isInteger(year)||year<1900||year>2100)return null;let q=Number($('quarterSelect').value),startMonth=period==='yearly'?1:(q-1)*3+1,endMonth=period==='yearly'?12:startMonth+2;let start=year+'-'+String(startMonth).padStart(2,'0')+'-01',end=year+'-'+String(endMonth).padStart(2,'0')+'-'+new Date(year,endMonth,0).getDate();return {start,end}}
 if(period==='weekly'){let value=$('date').value;if(!value)return null;let d=new Date(value+'T00:00:00Z');if(isNaN(d))return null;let day=d.getUTCDay();d.setUTCDate(d.getUTCDate()-((day+6)%7));let start=d.toISOString().slice(0,10);d.setUTCDate(d.getUTCDate()+6);return {start,end:d.toISOString().slice(0,10)}}
 return priorDates()
};
setPeriod=function(p){let old=$('date').value||'2026-10-21';period=p;$('periodSelect').value=p;$('date').type=p==='monthly'?'month':'date';$('date').value=p==='monthly'?old.slice(0,7):old.length===7?old+'-01':old;let annual=p==='quarterly'||p==='yearly';$('date').parentElement.style.display=annual?'none':'flex';$('yearField').style.display=annual?'flex':'none';$('quarterField').style.display=p==='quarterly'?'flex':'none';$('endField').hidden=p!=='custom';$('endField').style.display=p==='custom'?'flex':'none';$('dateLabel').textContent=p==='monthly'?'Month':p==='custom'?'From':p==='weekly'?'Week containing':'Date';render()};
const priorPeriodRender=render;
render=function(){priorPeriodRender();let labels={allYears:'All years',daily:'Daily',weekly:'Weekly',monthly:'Monthly',quarterly:'Quarterly',yearly:'Yearly',custom:'Custom range'};$('performanceTitle').textContent=labels[period]+' QC performance';if(period==='weekly')$('filterSummary').textContent+=' Weeks run Monday–Sunday.';if(period==='quarterly')$('filterSummary').textContent+=' Calendar quarter: Q'+$('quarterSelect').value+' · '+$('yearSelect').value+'.'};
