let {bs,ds}=scope(),totals=timeBuckets.map(b=>summarize(currentRecords.filter(r=>r.date>=b.start&&r.date<=b.end&&matches(r,bs,ds)))),s='';[0,25,50,75,100].forEach(n=>{let y=162-n*1.4;s+='<line x1="35" y1="'+y+'" x2="378" y2="'+y+'" stroke="#edf1f2"/><text x="26" y="'+(y+3)+'" fill="#9aa7ad" font-size="9" text-anchor="end">'+n+'%</text>'});let x=i=>timeBuckets.length===1?205:43+i*324/(timeBuckets.length-1);['passed','failed'].forEach((key,k)=>{let color=k?'#e76c6c':'#35B34A',points=[];totals.forEach((v,i)=>{let y=162-Number(pct(v[key],v.runs))*1.4;if(v.runs){points.push(x(i)+','+y);s+='<circle cx="'+x(i)+'" cy="'+y+'" r="3.5" fill="'+color+'"><title>'+timeBuckets[i].label+': '+pct(v[key],v.runs)+'%</title></circle>'}else{if(points.length)s+='<polyline points="'+points.join(' ')+'" fill="none" stroke="'+color+'" stroke-width="2"/>';points=[]}});s+='<polyline points="'+points.join(' ')+'" fill="none" stroke="'+color+'" stroke-width="2"/>'});
