function closeBranchChart(){$('branchChartView').hidden=true;$('branchTableView').hidden=false;$('branchChartCTA').setAttribute('aria-expanded','false');$('branchChartCTA').focus()}
function setBranchChartType(type){branchChartType=type;renderBranchChart()}
function renderBranchChart(){if($('branchChartView').hidden)return;let {bs,ds}=scope(),department=!!$('branch').value,names=department?ds:bs,metric=$('branchChartMetric').value,top=$('branchChartTop').value;let labels={samples:'Patient samples',runs:'QC runs',passed:'QC passed',failed:'QC failed',passRate:'Pass %',failRate:'Failure %',pending:'Pending actions'},percent=metric==='passRate'||metric==='failRate',colors=['#389b63','#2ca6df','#f2a01c','#8b62e5','#52b9b0','#d586a9'];let rows=names.map(name=>{let records=currentRecords.filter(r=>matches(r,department?bs:[name],department?[name]:ds)),a=summarize(records);return {name,value:metric==='passRate'?Number(pct(a.passed,a.runs)):metric==='failRate'?Number(pct(a.failed,a.runs)):metric==='pending'?records.filter(r=>r.result==='Failed'&&r.status==='Pending').length:a[metric]}}).sort((a,b)=>b.value-a.value);if(top!=='all')rows=rows.slice(0,Number(top));$('branchChartCategory').textContent=department?'Department':'Branch';$('branchChartTypes').innerHTML=['Bar','Column','Pie','Line','Area'].map(type=>'<button type="button" aria-pressed="'+(type===branchChartType)+'" onclick="setBranchChartType(\''+type+'\')">'+type+'</button>').join('');$('branchChartCaption').textContent=labels[metric]+' by '+(department?'department':'branch')+' · Current dates and filters · '+rows.length+' categories'+(branchChartType==='Pie'&&percent?' · Pie slices represent relative rates, not QC run shares.':'');let max=Math.max(1,...rows.map(r=>r.value)),value=v=>percent?v.toFixed(1)+'%':fmt(v),s='',W=900,H=360;
if(!rows.some(r=>r.value)){ $('branchChartCanvas').innerHTML='<p style="padding:60px;text-align:center;color:#82968a">No matching data for this metric.</p>';return}
if(branchChartType==='Bar'){H=Math.max(260,rows.length*55+65);for(let i=0;i<=4;i++){let x=170+i*650/4;s+='<line x1="'+x+'" y1="10" x2="'+x+'" y2="'+(H-40)+'" stroke="#e4eee6" stroke-dasharray="3 4"/><text x="'+x+'" y="'+(H-18)+'" font-size="11" text-anchor="middle" fill="#83998b">'+value(max*i/4)+'</text>'}rows.forEach((r,i)=>{let y=20+i*(H-65)/rows.length,width=r.value/max*630,color=metric==='failed'||metric==='failRate'?'#e46666':metric==='passed'||metric==='passRate'?'#35B34A':colors[i%colors.length];s+='<text x="158" y="'+(y+22)+'" text-anchor="end" font-size="12" fill="#6a8273">'+r.name+'</text><rect x="170" y="'+y+'" width="'+width+'" height="35" rx="5" fill="'+color+'"><title>'+r.name+': '+value(r.value)+'</title></rect><text x="'+(180+width)+'" y="'+(y+22)+'" font-size="11" fill="#395b46">'+value(r.value)+'</text>'})}
else if(branchChartType==='Pie'){let total=rows.reduce((a,r)=>a+r.value,0),offset=0;rows.forEach((r,i)=>{let part=r.value/total*628.32;s+='<circle cx="330" cy="170" r="100" fill="none" stroke="'+colors[i%colors.length]+'" stroke-width="90" stroke-dasharray="'+part+' '+(628.32-part)+'" stroke-dashoffset="'+(-offset)+'" transform="rotate(-90 330 170)"><title>'+r.name+': '+value(r.value)+'</title></circle>';offset+=part;s+='<rect x="550" y="'+(35+i*42)+'" width="10" height="10" rx="3" fill="'+colors[i%colors.length]+'"/><text x="575" y="'+(45+i*42)+'" font-size="13" fill="#657e70">'+r.name+' · '+value(r.value)+'</text>'})}
else{for(let i=0;i<=4;i++){let y=290-i*250/4;s+='<line x1="75" y1="'+y+'" x2="855" y2="'+y+'" stroke="#e4eee6"/><text x="65" y="'+(y+4)+'" text-anchor="end" font-size="11" fill="#83998b">'+value(max*i/4)+'</text>'}let points=[],step=750/Math.max(1,rows.length);rows.forEach((r,i)=>{let x=90+step*(i+.5),y=290-r.value/max*240;points.push([x,y]);s+='<text x="'+x+'" y="320" text-anchor="middle" font-size="11" fill="#6a8273">'+r.name+'</text>';if(branchChartType==='Column')s+='<rect x="'+(x-step*.27)+'" y="'+y+'" width="'+step*.54+'" height="'+(290-y)+'" rx="5" fill="'+(metric==='failed'||metric==='failRate'?'#e46666':colors[i%colors.length])+'"><title>'+r.name+': '+value(r.value)+'</title></rect>'});if(branchChartType!=='Column'){let color=metric==='failed'||metric==='failRate'?'#e46666':'#278436';if(branchChartType==='Area')s+='<polygon points="'+points[0][0]+',290 '+points.map(p=>p.join(',')).join(' ')+' '+points[points.length-1][0]+',290" fill="'+color+'22"/>';s+='<polyline points="'+points.map(p=>p.join(',')).join(' ')+'" fill="none" stroke="'+color+'" stroke-width="3"/>';points.forEach(([x,y],i)=>s+='<circle cx="'+x+'" cy="'+y+'" r="5" fill="'+color+'"><title>'+rows[i].name+': '+value(rows[i].value)+'</title></circle>')}}$('branchChartCanvas').innerHTML='<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+branchChartType+' chart: '+labels[metric]+' by '+(department?'department':'branch')+'">'+s+'</svg>'}
const branchChartRender=render;render=function(){let result=branchChartRender.apply(this,arguments);renderBranchChart();return result};$('branchChartCTA').setAttribute('aria-expanded','false');document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('branchChartView').hidden)closeBranchChart()});


function addBranchViewActions(){let {bs,ds}=scope(),names=$('branch').value?ds:bs;Array.from($('rows').children).forEach((row,index)=>{let name=names[index];if(!name)return;let cell=row.querySelector('[data-branch-view]');if(!cell){cell=document.createElement('td');cell.setAttribute('data-branch-view','');row.appendChild(cell)}cell.replaceChildren();let button=document.createElement('button');button.type='button';button.className='back';button.textContent='View';button.setAttribute('aria-label','View '+name+' QC performance');button.onclick=()=>drill(name);cell.appendChild(button)})}
const branchViewRender=render;render=function(){let result=branchViewRender.apply(this,arguments);addBranchViewActions();return result};addBranchViewActions();


(()=>{let tip=document.createElement('div');tip.className='unified-chart-tooltip';tip.setAttribute('role','tooltip');tip.hidden=true;document.body.appendChild(tip);let active=null,original=null;function clear(){tip.hidden=true;if(active&&original){if(original.radius!==null){active.setAttribute('r',original.radius);active.setAttribute('stroke-width',original.width);active.style.filter=original.filter}}active=null;original=null}function place(event){let width=tip.offsetWidth,height=tip.offsetHeight,left=event.clientX+16,top=event.clientY+16;if(left+width>innerWidth-12)left=event.clientX-width-16;if(top+height>innerHeight-12)top=event.clientY-height-16;tip.style.left=Math.max(12,left)+'px';tip.style.top=Math.max(12,top)+'px'}document.addEventListener('pointerover',event=>{let shape=event.target.closest('svg rect,svg circle,svg path,svg polygon');if(!shape||shape===active||shape.closest('#bars')&&typeof showQC==='function')return;let title=shape.querySelector('title')||{textContent:shape.getAttribute('data-chart-title')||'',remove(){}};if(!title.textContent.trim())return;clear();active=shape;let text=title.textContent.trim(),index=text.indexOf(': '),label=index>=0?text.slice(0,index):text,value=index>=0?text.slice(index+2):'',radius=shape.tagName.toLowerCase()==='circle'&&shape.hasAttribute('stroke-dasharray')&&Number(shape.getAttribute('stroke-width'))>=15?shape.getAttribute('r'):null;original={radius,width:shape.getAttribute('stroke-width'),filter:shape.style.filter};shape.setAttribute('data-chart-title',title.textContent);title.remove();tip.replaceChildren();let heading=document.createElement('strong');heading.textContent=label;tip.appendChild(heading);if(value){let metric=document.createElement('span');metric.className='hover-value'+(/fail|reject|refund/i.test(label)?' hover-failure':'');metric.textContent=value;let chartColor=shape.getAttribute('fill');if(!chartColor||chartColor==='none'||chartColor==='transparent'||chartColor==='#fff'||chartColor==='white')chartColor=shape.getAttribute('stroke');if(chartColor&&chartColor!=='none'&&chartColor!=='transparent')metric.style.color=chartColor;tip.appendChild(metric)}if(radius!==null){shape.setAttribute('stroke-width',Number(original.width)*1.10);shape.style.filter='brightness(1.04)'}tip.hidden=false;place(event)});document.addEventListener('pointermove',event=>{if(active)place(event)});document.addEventListener('pointerout',event=>{if(active&&event.target===active)clear()});document.addEventListener('scroll',clear,true);document.addEventListener('click',clear);document.addEventListener('keydown',event=>{if(event.key==='Escape')clear()});window.addEventListener('resize',clear)})();


(()=>{function upgrade(){document.querySelectorAll('button:not(.reference-menu):not(.select-trigger)').forEach(button=>{if(button.querySelector('[data-lucide-button]'))return;let label=button.textContent.trim(),name=/Export|Excel.?CSV/i.test(label)?'Download':/More filters/i.test(label)?'Filter':/^Clear|^Reset/i.test(label)?'RotateCcw':/^←|Back/i.test(label)?'ArrowLeft':/^View/i.test(label)?'ArrowUpRight':/^×$/.test(label)?'X':/^↻$/.test(label)?'RotateCcw':/^Bar$/.test(label)?'ChartBar':/^Column$/.test(label)?'ChartColumn':/^Pie$/.test(label)?'ChartPie':/^Line$/.test(label)?'ChartLine':/^Area$/.test(label)?'ChartArea':/Chart/i.test(label)&&!label.includes('selection')?'ChartColumn':null;if(!name)return;button.querySelectorAll('svg').forEach(node=>node.remove());Array.from(button.childNodes).filter(node=>node.nodeType===3).forEach(node=>node.textContent=node.textContent.replace(/[▥▦↓↗←↻▽×]/g,'').trim());let holder=document.createElement('span');holder.className='lucide-button-icon';holder.setAttribute('data-lucide-button',name);holder.innerHTML=dashboardIcon(name);button.insertBefore(holder,button.firstChild);if(!button.textContent.trim()&&!button.getAttribute('aria-label'))button.setAttribute('aria-label',name)});document.querySelectorAll('.metric-icon').forEach((node,index)=>{if(node.querySelector('.lucide-ui'))return;node.innerHTML=dashboardIcon(['Banknote','Receipt','Users','TestTube','Package','CalendarClock','CircleX'][index%7])});document.querySelectorAll('#panelTabs button').forEach(button=>{if(button.querySelector('.lucide-ui'))return;let label=button.textContent,name=label.includes('Canonical')?'Layers':label.includes('Component')?'FlaskConical':'ClipboardList';button.querySelectorAll('svg').forEach(node=>node.remove());let span=document.createElement('span');span.innerHTML=dashboardIcon(name);button.insertBefore(span.firstChild,button.firstChild)})}let scheduled=false;new MutationObserver(()=>{if(scheduled)return;scheduled=true;queueMicrotask(()=>{scheduled=false;upgrade()})}).observe(document.body,{childList:true,subtree:true});upgrade()})();


// Preserve chart metadata while suppressing the browser's duplicate native tooltip.
document.addEventListener('pointerover',event=>{let mark=event.target.closest('svg rect,svg circle,svg path,svg polygon');if(!mark)return;let title=mark.querySelector('title');if(title){mark.setAttribute('data-chart-title',title.textContent);if(!mark.hasAttribute('aria-label'))mark.setAttribute('aria-label',title.textContent);title.remove()}},true);


(()=>{function alignClose(){document.querySelectorAll('.rev-chart').forEach(panel=>{let row=panel.querySelector('.revenue-chart-toolbar');if(!row)return;let button=panel.querySelector('.rev-close');if(!button){let id=panel.id.replace('chart-','');button=document.createElement('button');button.type='button';button.className='rev-close';button.setAttribute('aria-label','Close chart');button.innerHTML=dashboardIcon('X');button.onclick=()=>toggleRevenueChart(id)}button.classList.add('chart-toolbar-close');if(button.parentNode!==row)row.appendChild(button)});document.querySelectorAll('.specialty-chart').forEach(panel=>{let row=panel.querySelector('.specialty-chart-controls');if(!row)return;let button=panel.querySelector('.rev-close');if(!button){let id=panel.id.replace('specialChart-','');button=document.createElement('button');button.type='button';button.className='rev-close';button.setAttribute('aria-label','Close chart');button.innerHTML=dashboardIcon('X');button.onclick=()=>toggleSpecialChart(id)}button.classList.add('chart-toolbar-close');if(button.parentNode!==row)row.appendChild(button)});let panel=document.getElementById('reportInlineChart');if(panel){let row=panel.querySelector('.tp-chart-types'),button=panel.querySelector('.tests-chart-close');if(row&&button){button.classList.add('chart-toolbar-close');if(button.parentNode!==row)row.appendChild(button)}}let branch=document.getElementById('branchChartView');if(branch){let row=branch.querySelector('.branch-chart-controls'),button=branch.querySelector('.branch-chart-close');if(row&&button){button.classList.add('chart-toolbar-close');if(button.parentNode!==row)row.appendChild(button)}}}let queued=false;new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;alignClose()})}).observe(document.body,{childList:true,subtree:true});alignClose()})();
